mapper.select:
SELECT a.id, a.user_id, a.expert_id, a.appointment_time, a.note, a.contact_phone, a.status, a.created_at, a.updated_at, e.username as expert_name FROM expert_appointment a LEFT JOIN sys_user e ON a.expert_id = e.id WHERE a.user_id = #{userId}
AND a.status = #{status}
ORDER BY a.created_at DESC

SELECT a.id, a.user_id, a.expert_id, a.appointment_time, a.note, a.contact_phone, a.status, a.created_at, a.updated_at, u.username as user_name FROM expert_appointment a LEFT JOIN sys_user u ON a.user_id = u.id WHERE a.expert_id = #{expertId}
AND a.status = #{status}
ORDER BY a.created_at DESC
